def canFormArray(arr, pieces):
    first_elem_map = {piece[0]: piece for piece in pieces}
    i = 0
    while i < len(arr):
        if arr[i] not in first_elem_map:
            return False
        piece = first_elem_map[arr[i]]
        if arr[i:i+len(piece)] != piece:
            return False
        i += len(piece)
    return True
